export default function urgentGmailProgress({ events, previousState }) {
  if (!Array.isArray(events) || events.length > 50) throw new Error("Invalid Gmail poll page");
  for (const e of events)
    if (!e || typeof e.messageId !== "string" || !e.messageId || typeof e.subject !== "string")
      throw new Error("Invalid Gmail event");
  let index = 0;
  if (previousState != null) {
    if (
      !Number.isInteger(previousState.index) ||
      previousState.index < 0 ||
      previousState.index >= events.length
    )
      throw new Error("Invalid Gmail page progress");
    index = previousState.index + 1;
  }
  const current = events[index];
  return {
    state: { index },
    more: index < events.length,
    matched: !!current && (current.subject.includes("Urgent") || current.subject === "Server Down"),
    messageId: current?.messageId ?? "",
    subject: current?.subject ?? "",
    count: index,
  };
}

