export default function urgentGmailMessage({
  expectedId,
  expectedSubject,
  messageId,
  subject,
  sender,
  snippet,
  chatId,
}) {
  if (messageId !== expectedId || subject !== expectedSubject)
    throw new Error("Gmail message changed or did not match the event");
  if (typeof sender !== "string" || (snippet != null && typeof snippet !== "string"))
    throw new Error("Invalid Gmail message fields");
  if (typeof chatId !== "string" || !chatId || chatId === "@YOUR_TELEGRAM_CHAT")
    throw new Error("Set the Telegram chat ID");
  const plain =
    "From : " + sender + "\nSubject :" + subject + "\nMessage : " + (snippet ?? "") + "\n";
  const text =
    "<pre>" + plain.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;") + "</pre>";
  if (text.length > 4096) throw new Error("Telegram message exceeds 4096 characters");
  return { chatId, text };
}
